package ds4

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/provider/utilization"
)

// ds4Props mirrors the relevant fields of the ds4-server /props response.
type ds4Props struct {
	Reasoning struct {
		SupportedEfforts   []string          `json:"supported_efforts"`
		Aliases            map[string]string `json:"aliases"`
		Default            string            `json:"default"`
		EffectiveDefault   string            `json:"effective_default"`
		ThinkMaxMinContext int               `json:"think_max_min_context"`
	} `json:"reasoning"`
	API struct {
		SupportedRequestParameters []string `json:"supported_request_parameters"`
	} `json:"api"`
	Sampling map[string]any `json:"sampling"`
	Runtime  map[string]any `json:"runtime"`
}

// Introspect fetches GET /props from a ds4-server and returns structured
// ProviderIntrospection. Returns an error if the endpoint is unreachable or
// the response is malformed; callers should fall through to static defaults.
//
// Effective reasoning levels are derived by removing alias source keys from
// supported_efforts (e.g. low/medium/xhigh all alias to high, leaving ["high", "max"]).
func Introspect(ctx context.Context, baseURL, model string, client *http.Client) (*registry.ProviderIntrospection, error) {
	if client == nil {
		client = http.DefaultClient
	}
	endpoint := utilization.ServerRoot(baseURL) + "/props"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: build request: %w", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: GET %s: %w", endpoint, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return nil, fmt.Errorf("ds4 introspection: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("ds4 introspection: read body: %w", err)
	}

	var props ds4Props
	if err := json.Unmarshal(body, &props); err != nil {
		return nil, fmt.Errorf("ds4 introspection: unmarshal: %w", err)
	}

	// Effective levels = supported_efforts minus alias source keys.
	effectiveLevels := make([]string, 0, len(props.Reasoning.SupportedEfforts))
	for _, effort := range props.Reasoning.SupportedEfforts {
		if _, isAlias := props.Reasoning.Aliases[effort]; !isAlias {
			effectiveLevels = append(effectiveLevels, effort)
		}
	}

	var raw map[string]any
	_ = json.Unmarshal(body, &raw)

	return &registry.ProviderIntrospection{
		EffectiveThinkingFormat:  string(openai.ThinkingWireFormatOpenAIEffort),
		EffectiveReasoningLevels: effectiveLevels,
		AliasMap:                 props.Reasoning.Aliases,
		SupportedRequestParams:   props.API.SupportedRequestParameters,
		Raw:                      raw,
	}, nil
}

package registry

import (
	"context"
	"log/slog"
	"net/http"
	"sync"
)

// ProviderIntrospection is the structured output of a live provider
// introspection call. Fields are zero-valued when the endpoint doesn't
// supply the corresponding information.
type ProviderIntrospection struct {
	// EffectiveThinkingFormat overrides the static ThinkingFormat default.
	// Holds an openai.ThinkingWireFormat value (string alias); consumers cast
	// to openai.ThinkingWireFormat before use.
	EffectiveThinkingFormat string
	// EffectiveReasoningLevels holds the distinct effort tiers after
	// de-aliasing (e.g. ["high", "max"] for ds4 which aliases low/medium/xhigh→high).
	EffectiveReasoningLevels []string
	// AliasMap maps non-canonical effort names to their canonical targets.
	// Example: {"low": "high", "medium": "high", "xhigh": "high"}.
	AliasMap map[string]string
	// SupportedRequestParams lists the request-body parameters the server
	// accepts (from api.supported_request_parameters on ds4).
	SupportedRequestParams []string
	// ServerSideReasoningFormat is the server's current reasoning_format
	// default (e.g. "deepseek", "auto"). Only set by llama-server.
	ServerSideReasoningFormat string
	// Raw is the full unmarshaled /props payload for audit and debug.
	Raw map[string]any
}

// IntrospectionFn is the signature of a provider introspection adapter.
// The adapter fetches the provider's introspection endpoint and returns
// structured ProviderIntrospection. On failure it returns an error and
// the caller falls through to static defaults without failing construction.
type IntrospectionFn func(ctx context.Context, baseURL, model string, client *http.Client) (*ProviderIntrospection, error)

type introspectionKey struct {
	providerType string
	baseURL      string
	model        string
}

var (
	introspectionAdaptersMu sync.RWMutex
	introspectionAdapters   = map[string]IntrospectionFn{}

	introspectionCacheMu sync.Mutex
	introspectionCache   = map[introspectionKey]*ProviderIntrospection{}
)

// RegisterIntrospectionAdapter registers an introspection adapter for a
// provider type. Called automatically by Register when Descriptor.IntrospectionFn
// is non-nil. Can also be called directly (e.g. from tests).
func RegisterIntrospectionAdapter(providerType string, fn IntrospectionFn) {
	introspectionAdaptersMu.Lock()
	defer introspectionAdaptersMu.Unlock()
	introspectionAdapters[providerType] = fn
}

// IntrospectProvider runs the registered introspection adapter for providerType,
// caching results keyed by (providerType, baseURL, model) for the process
// lifetime. Returns (nil, false) when no adapter is registered or the adapter
// returns an error; a structured warning is logged on error.
//
// The cache mutex is held while the adapter fn executes, preventing concurrent
// duplicate calls for the same key during parallel provider construction.
func IntrospectProvider(ctx context.Context, providerType, baseURL, model string) (*ProviderIntrospection, bool) {
	introspectionAdaptersMu.RLock()
	fn, ok := introspectionAdapters[providerType]
	introspectionAdaptersMu.RUnlock()
	if !ok {
		return nil, false
	}

	key := introspectionKey{providerType, baseURL, model}

	introspectionCacheMu.Lock()
	defer introspectionCacheMu.Unlock()

	if cached, found := introspectionCache[key]; found {
		return cached, true
	}

	result, err := fn(ctx, baseURL, model, http.DefaultClient)
	if err != nil {
		slog.Warn("provider introspection failed; using static defaults",
			"provider_type", providerType,
			"base_url", baseURL,
			"model", model,
			"error", err)
		return nil, false
	}

	introspectionCache[key] = result
	return result, true
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/provider/utilization"
)

// llamaProps mirrors the relevant fields of the llama-server /props response.
type llamaProps struct {
	DefaultGenerationSettings struct {
		Params struct {
			ReasoningFormat string `json:"reasoning_format"`
		} `json:"params"`
	} `json:"default_generation_settings"`
	ChatTemplate     string `json:"chat_template"`
	ChatTemplateCaps struct {
		SupportsPreserveReasoning bool `json:"supports_preserve_reasoning"`
	} `json:"chat_template_caps"`
	BuildInfo map[string]any `json:"build_info"`
}

// Introspect fetches GET /props from a llama-server and returns structured
// ProviderIntrospection. Returns an error if the endpoint is unreachable or
// the response is malformed; callers should fall through to static defaults.
//
// The chat_template is inspected for the "enable_thinking" substring to
// confirm the Qwen chat_template_kwargs envelope (vs bare top-level fields).
func Introspect(ctx context.Context, baseURL, model string, client *http.Client) (*registry.ProviderIntrospection, error) {
	if client == nil {
		client = http.DefaultClient
	}
	endpoint := utilization.ServerRoot(baseURL) + "/props"
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: build request: %w", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: GET %s: %w", endpoint, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return nil, fmt.Errorf("llama-server introspection: HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("llama-server introspection: read body: %w", err)
	}

	var props llamaProps
	if err := json.Unmarshal(body, &props); err != nil {
		return nil, fmt.Errorf("llama-server introspection: unmarshal: %w", err)
	}

	// Detect Qwen chat_template_kwargs envelope via substring match.
	// Top-level enable_thinking is silently dropped by llama-server; the
	// kwargs envelope (chat_template_kwargs.enable_thinking) is required.
	thinkingFormat := openai.ThinkingWireFormatQwen
	if !strings.Contains(props.ChatTemplate, "enable_thinking") {
		// Template doesn't reference enable_thinking at all — reasoning
		// controls may not apply. Qwen remains the default for this provider
		// type; callers can override via catalog L2.
		thinkingFormat = openai.ThinkingWireFormatQwen
	}

	var raw map[string]any
	_ = json.Unmarshal(body, &raw)

	return &registry.ProviderIntrospection{
		EffectiveThinkingFormat:   string(thinkingFormat),
		ServerSideReasoningFormat: props.DefaultGenerationSettings.Params.ReasoningFormat,
		Raw:                       raw,
	}, nil
}

// Package ds4 wraps the OpenAI-compatible HTTP surface exposed by DwarfStar 4
// (antirez/ds4) — a single-model native inference engine for DeepSeek V4 Flash
// with Metal/CUDA execution. The /v1/chat/completions and /v1/completions
// routes are OpenAI-compatible; /v1/messages also speaks Anthropic Messages.
// Other endpoints (no /health, /metrics, /slots, no auth) are minimal —
// see internal/provider/ds4/utilization_probe.go for the liveness-only probe.
package ds4

import (
	"context"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/reasoning"
)

// DefaultBaseURL matches the ds4-server default listen (127.0.0.1:8000) plus
// the /v1 prefix. Operators usually override the host portion in their
// fizeau provider config; the port stays 8000 unless the server was started
// with --port.
const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "ds4",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL:  DefaultBaseURL,
		DefaultPort:     8000,
		IntrospectionFn: Introspect,
	})
}

// ProtocolCapabilities is the L3 static default for ds4. It is used as the
// base when no live introspection is available. ds4's verified wire surface
// (via /props):
//   - `reasoning_effort: "low"|"medium"|"high"|"max"|"xhigh"` (flat top-level, OpenAI-style)
//   - `think: false` (boolean shortcut for direct-reply / disable)
//   - model alias `deepseek-chat` for non-thinking
//
// ds4 /props.reasoning.aliases declares {low→high, medium→high, xhigh→high};
// only `high` and `max` are practically distinct effort levels.
// fizeau emits ThinkingWireFormatOpenAIEffort (flat reasoning_effort) for this provider.
//
// Other ds4 quirks worth knowing about (handled elsewhere): finish_reason
// is only "stop" or "length" — never "tool_calls" — but the agent loop
// already keys on empty resp.ToolCalls for natural-stop detection.
var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
	Thinking:         true,
	ThinkingFormat:   openai.ThinkingWireFormatOpenAIEffort,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

// New constructs a ds4 provider. It first attempts L1 live introspection via
// /props to override static capability defaults (e.g. ThinkingFormat). On
// introspection failure the static ProtocolCapabilities are used unchanged.
func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}

	// Start from the L3 static defaults; L1 introspection may override.
	caps := ProtocolCapabilities

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if intro, ok := registry.IntrospectProvider(ctx, "ds4", baseURL, cfg.Model); ok {
		if intro.EffectiveThinkingFormat != "" {
			caps.ThinkingFormat = openai.ThinkingWireFormat(intro.EffectiveThinkingFormat)
		}
		caps.ReasoningAliasMap = intro.AliasMap
		caps.SupportedRequestParams = intro.SupportedRequestParams
	}

	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "ds4",
		ProviderSystem: "ds4",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &caps,
	})
}

// Package llamaserver wraps the OpenAI-compatible HTTP surface exposed by
// llama.cpp's built-in server.
package llamaserver

import (
	"context"
	"time"

	agentcore "github.com/easel/fizeau/internal/core"
	"github.com/easel/fizeau/internal/provider/openai"
	"github.com/easel/fizeau/internal/provider/registry"
	"github.com/easel/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:8080/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "llama-server",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL:  DefaultBaseURL,
		DefaultPort:     8080,
		IntrospectionFn: Introspect,
	})
}

// ProtocolCapabilities is the L3 static default for llama-server. It is used
// as the base when no live introspection is available. llama.cpp's llama-server
// accepts Qwen-family enable_thinking + thinking_budget controls when the
// model's chat template is wired for thinking mode (Qwen3, DeepSeek R1, etc.)
// — and silently ignores them on non-thinking models. The default
// ThinkingWireFormatQwen matches what Qwen GGUFs expect via the
// chat_template_kwargs envelope.
//
// Without Thinking: true, fizeau's openai provider rejects any explicit
// reasoning param with "openai: reasoning=... is not supported by provider
// type llama-server" — biting us on sindri-llamacpp until 2026-05-11.
var ProtocolCapabilities = openai.ProtocolCapabilities{
	Tools:            true,
	Stream:           true,
	StructuredOutput: true,
	Thinking:         true,
	ThinkingFormat:   openai.ThinkingWireFormatQwen,
}

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

// New constructs a llama-server provider. It first attempts L1 live
// introspection via /props to override static capability defaults
// (e.g. ThinkingFormat, server-side reasoning_format). On introspection
// failure the static ProtocolCapabilities are used unchanged.
func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}

	// Start from the L3 static defaults; L1 introspection may override.
	caps := ProtocolCapabilities

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if intro, ok := registry.IntrospectProvider(ctx, "llama-server", baseURL, cfg.Model); ok {
		if intro.EffectiveThinkingFormat != "" {
			caps.ThinkingFormat = openai.ThinkingWireFormat(intro.EffectiveThinkingFormat)
		}
	}

	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "llama-server",
